import{_ as a,C as d,o as r,c as s,E as n,a3 as o}from"./chunks/framework.CCylkYel.js";const i="/screens/devices/envelope.png",b=JSON.parse('{"title":"Envelope","description":"","frontmatter":{"title":"Envelope","pageClass":"device-doc"},"headers":[],"relativePath":"devices/envelope.md","filePath":"devices/envelope.md"}'),l={name:"devices/envelope.md"};function h(g,t,c,p,y,m){const e=d("DeviceHeading");return r(),s("div",null,[n(e,{slug:"envelope",title:"Envelope"}),t[0]||(t[0]=o('<p>ADSR envelope on MIDI</p><p><img src="'+i+'" alt="Envelope parameters" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Place <strong>Envelope</strong> when a <strong>CC, pitch bend, or other MIDI destination</strong> should follow an ADSR shape triggered by notes or a fixed key.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Attack, Hold, Decay, and Release share one 0–768 number. <strong>Sync SYNCED</strong> (default) is 24-PPQN ticks. Values that land on a standard beat show a note name (<strong>1/16</strong>, <strong>1/8</strong>, <strong>1/4</strong>, <strong>1/2</strong>, <strong>1/1</strong>, <strong>2 BARS</strong>, …). Other times still show ticks with <strong>T</strong>. The encoder steps those named beats; the stored number is still ticks. Switching to <strong>SYNCED</strong> snaps leftover FREE times onto the nearest named beat. <strong>Sync FREE</strong> uses the same numbers as milliseconds (no note names) and runs without MIDI Clock.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Bypass</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>Trigger</td><td>0</td><td>What starts the envelope: mono, keyed, polyphonic, or looping.</td></tr><tr><td>Key Note</td><td>0 – 127</td><td>MIDI note that retriggers the envelope in Key mode.</td></tr><tr><td>Sync</td><td>0 – 1</td><td>SYNCED (default) uses 24-PPQN ticks; FREE uses the same 0–768 numbers as milliseconds.</td></tr><tr><td>Attack</td><td>0 – 768</td><td>Time to reach peak after trigger (ticks with note names when SYNCED, or ms when FREE).</td></tr><tr><td>Hold</td><td>0 – 768</td><td>Time peak is held before decay (ticks with note names when SYNCED, or ms when FREE).</td></tr><tr><td>Decay</td><td>0 – 768</td><td>Time to fall from peak to sustain (ticks with note names when SYNCED, or ms when FREE).</td></tr><tr><td>Sustain</td><td>0 – 100</td><td>Held level while the note is down (0–100%).</td></tr><tr><td>Release</td><td>0 – 768</td><td>Time the note stays held after you let go, while Dest fades (ticks with note names when SYNCED, or ms when FREE). NoteOff is sent when Release finishes. Loop still passes NoteOff through immediately.</td></tr><tr><td>Curve</td><td>0 – 1</td><td>Shape of Attack, Decay, and Release: LINEAR ramps or LOG (faster start, eases into the target).</td></tr><tr><td>Depth</td><td>-100 – 100</td><td>Modulation amount applied to the destination (−100 to +100%).</td></tr><tr><td>Offset</td><td>0 – 100</td><td>Baseline level before the envelope shape (0–100%).</td></tr><tr><td>Dest</td><td>0</td><td>MIDI message type the envelope drives (CC, NRPN, pitch bend, etc.).</td></tr><tr><td>Dest MSB</td><td>0 – 127</td><td>High byte of the destination address (NRPN/RPN/CC MSB).</td></tr><tr><td>Dest LSB</td><td>0 – 127</td><td>Low byte of the destination address (NRPN/RPN/CC number).</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>On</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Mono</td><td>Single envelope retriggers on any note.</td></tr><tr><td style="text-align:right;">1</td><td>Key</td><td>Retrigger only from Trigger Key.</td></tr><tr><td style="text-align:right;">2</td><td>Poly</td><td>Independent envelope per held note.</td></tr><tr><td style="text-align:right;">3</td><td>Loop</td><td>Retrigger continuously while held.</td></tr></tbody></table><h3 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>FREE</td><td>Phase times are milliseconds; the envelope runs without MIDI Clock.</td></tr><tr><td style="text-align:right;">1</td><td>SYNCED</td><td>Phase times are 24-PPQN ticks (default). Follows MIDI Clock.</td></tr></tbody></table><h3 id="curve" tabindex="-1">Curve <a class="header-anchor" href="#curve" aria-label="Permalink to &quot;Curve&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>LINEAR</td><td>Attack, Decay, and Release are straight ramps.</td></tr><tr><td style="text-align:right;">1</td><td>LOG</td><td>Attack, Decay, and Release use a log-shaped ramp (faster start, eases into the target).</td></tr></tbody></table><h3 id="attack-hold-decay-release-synced" tabindex="-1">Attack, Hold, Decay, Release (SYNCED) <a class="header-anchor" href="#attack-hold-decay-release-synced" aria-label="Permalink to &quot;Attack, Hold, Decay, Release (SYNCED)&quot;">​</a></h3><p>On <strong>SYNCED</strong>, a value that matches a 24-PPQN subdivision shows the same note names as Arp / Seed Rate. Off-grid values keep the tick number and <strong>T</strong>. Switching Sync to <strong>SYNCED</strong> snaps leftover FREE times onto the nearest named beat. On <strong>FREE</strong>, the same numbers are milliseconds — <strong>6</strong> is 6 ms, not <strong>1/16</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Ticks</th><th>Name</th></tr></thead><tbody><tr><td style="text-align:right;">2</td><td>1/64</td></tr><tr><td style="text-align:right;">3</td><td>1/32</td></tr><tr><td style="text-align:right;">6</td><td>1/16</td></tr><tr><td style="text-align:right;">12</td><td>1/8</td></tr><tr><td style="text-align:right;">24</td><td>1/4</td></tr><tr><td style="text-align:right;">48</td><td>1/2</td></tr><tr><td style="text-align:right;">96</td><td>1/1</td></tr><tr><td style="text-align:right;">192</td><td>2 BARS</td></tr><tr><td style="text-align:right;">384</td><td>4 BARS</td></tr><tr><td style="text-align:right;">768</td><td>8 BARS</td></tr></tbody></table><h3 id="dest" tabindex="-1">Dest <a class="header-anchor" href="#dest" aria-label="Permalink to &quot;Dest&quot;">​</a></h3><p>Picker order is usage-first. <strong>Value</strong> is the stored Dest integer (unchanged in saved projects). <strong>Poly AT</strong> appears only when Trigger is Poly. <strong>RPN</strong> is next to NRPN in every Trigger mode. <strong>Prog. Change</strong> is last because a running envelope would spray patch changes.</p><p>When Trigger is <strong>Poly</strong> and Dest is <strong>Poly AT</strong>, each held note sends its own aftertouch. Any other Dest (CC, RPN, pitch bend, …) is one shared message that follows the loudest sounding note.</p><p><strong>Release</strong> holds the MIDI note while Dest fades, then sends NoteOff when the fade finishes. That applies to <strong>Mono</strong> (the last held note), <strong>Poly</strong> (that voice), and <strong>Key</strong> (the trigger key). <strong>Loop</strong> still passes NoteOff through as soon as you let go. Release <strong>0</strong> is instant NoteOff.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>CC</td><td>Drive a single control change.</td></tr><tr><td style="text-align:right;">3</td><td>Pitch Bend</td><td>Channel pitch wheel.</td></tr><tr><td style="text-align:right;">4</td><td>Ch. Pressure</td><td>Aftertouch (channel).</td></tr><tr><td style="text-align:right;">6</td><td>Poly AT</td><td>Per-note pressure. Poly trigger only.</td></tr><tr><td style="text-align:right;">1</td><td>CC 14-bit</td><td>14-bit CC (MSB + LSB).</td></tr><tr><td style="text-align:right;">2</td><td>NRPN</td><td>Non-registered parameter number.</td></tr><tr><td style="text-align:right;">7</td><td>RPN</td><td>Registered parameter number.</td></tr><tr><td style="text-align:right;">5</td><td>Prog. Change</td><td>Patch change messages.</td></tr></tbody></table>',24))])}const f=a(l,[["render",h]]);export{b as __pageData,f as default};
